import subprocess,json,hashlib
from pathlib import Path
base="84e633fe53990951b96680295ab66daee60a8af2"
target="d24655fbfb56317a4c00ca5323fd8201692e0a32"
root=Path.cwd().parent
actual=set(subprocess.check_output(["git","diff","--name-only","-z",base,target],cwd=root).decode().strip("\0").split("\0"))
actual={p for p in actual if p.startswith("policy-engine/") and p.endswith(".py")}
def tree(ref):
    result={}
    for record in subprocess.check_output(["git","ls-tree","-rz",ref],cwd=root).split(b"\0"):
        if record:
            meta,name=record.split(b"\t",1)
            name=name.decode()
            if name.startswith("policy-engine/") and name.endswith(".py"):
                result[name]=meta.split()[2]
    return result
old,new=tree(base),tree(target)
independent={p for p in old.keys()|new.keys() if p not in old or p not in new or old[p]!=new[p]}
assert actual==independent
paths=sorted(p.removeprefix("policy-engine/") for p in actual)
print(json.dumps({"base":base,"target":target,"denominator":"Every changed tracked product Python file, complete git diff and independently compared recursive tree blob maps","changed_count":len(paths),"identity_sets_equal":True,"identity_digest":hashlib.sha256("\n".join(paths).encode()).hexdigest(),"missing":[],"unexpected":[],"ambiguous":[]},sort_keys=True))
